-- Calendario laboral: MX_CDMX 2024-2025, ES_MADRID 2025, US_TX 2025\n-- Sin festivos (los oficiales se añaden con otro script o por API).\n\nINSERT INTO business_calendar (jurisdiction_id, calendar_date, is_business_day, source)\nSELECT 'MX_CDMX', d::date,\n       EXTRACT(DOW FROM d) NOT IN (0, 6),\n       'SEED_MX_2024'\n  FROM generate_series('2024-01-01'::date, '2024-12-31'::date, '1 day') d\n  ON CONFLICT (jurisdiction_id, calendar_date) DO NOTHING;\n\nINSERT INTO business_calendar (jurisdiction_id, calendar_date, is_business_day, source)\nSELECT 'MX_CDMX', d::date,\n       EXTRACT(DOW FROM d) NOT IN (0, 6),\n       'SEED_MX_2025'\n  FROM generate_series('2025-01-01'::date, '2025-12-31'::date, '1 day') d\n  ON CONFLICT (jurisdiction_id, calendar_date) DO NOTHING;\n\n-- Festivos oficiales MX 2025 (LFT art. 74)\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Año Nuevo'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-01-01';\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Día de la Constitución'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-02-03';\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Natalicio Benito Juárez'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-03-17';\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Día del Trabajo'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-05-01';\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Día de la Independencia'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-09-16';\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Día de la Revolución'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-11-17';\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Transmisión Poder Ejecutivo'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-10-01';\nUPDATE business_calendar SET is_business_day = false, holiday_name = 'Navidad'\n WHERE jurisdiction_id = 'MX_CDMX' AND calendar_date = '2025-12-25';\n\nINSERT INTO business_calendar (jurisdiction_id, calendar_date, is_business_day, source)\nSELECT 'ES_MADRID', d::date,\n       EXTRACT(DOW FROM d) NOT IN (0, 6),\n       'SEED_ES_2025'\n  FROM generate_series('2025-01-01'::date, '2025-12-31'::date, '1 day') d\n  ON CONFLICT (jurisdiction_id, calendar_date) DO NOTHING;\n\nINSERT INTO business_calendar (jurisdiction_id, calendar_date, is_business_day, source)\nSELECT 'US_TX', d::date,\n       EXTRACT(DOW FROM d) NOT IN (0, 6),\n       'SEED_TX_2025'\n  FROM generate_series('2025-01-01'::date, '2025-12-31'::date, '1 day') d\n  ON CONFLICT (jurisdiction_id, calendar_date) DO NOTHING;